<section class="panel"><header class="panel-head"><div><span class="eyebrow">Supplier acknowledgment & shipment control</span><h2>PO fulfillment governance</h2></div><?= badge($selected['shipment_status']) ?></header><div class="fulfillment-kpis"><div><span>Ordered</span><strong><?= h(date_us($selected['order_date'])) ?></strong></div><div><span>Expected</span><strong><?= h(date_us($selected['expected_date'])) ?></strong></div><div><span>Acknowledged</span><strong><?= h($selected['supplier_acknowledged_at']?date_us(substr((string)$selected['supplier_acknowledged_at'],0,10)):'Not recorded') ?></strong></div></div><?php if(can('purchase_orders.edit')): ?><form class="compact-form" action="<?= h(app_url('fulfillment-action.php')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save_fulfillment"><input type="hidden" name="purchase_order_id" value="<?= (int)$selected['id'] ?>"><label><span>Shipment status</span><select name="shipment_status"><?php foreach(fulfillment_shipment_statuses() as $value): ?><option value="<?= h($value) ?>" <?= $selected['shipment_status']===$value?'selected':'' ?>><?= h(status_label($value)) ?></option><?php endforeach; ?></select></label><label><span>Supplier acknowledged</span><input type="datetime-local" name="supplier_acknowledged_at" value="<?= h($selected['supplier_acknowledged_at']?date('Y-m-d\TH:i',strtotime((string)$selected['supplier_acknowledged_at'])):'') ?>"></label><label><span>ASN number</span><input name="asn_number" value="<?= h($selected['asn_number']) ?>"></label><label><span>Carrier</span><input name="carrier" value="<?= h($selected['carrier']) ?>"></label><label><span>Tracking number</span><input name="tracking_number" value="<?= h($selected['tracking_number']) ?>"></label><label><span>Owner / reviewer</span><span><select name="owner_id"><?= user_options($selected['owner_id']) ?></select><select name="reviewer_id"><?= user_options($selected['reviewer_id']) ?></select></span></label><label class="span-2"><span>Shipment reference</span><textarea name="shipment_reference"><?= h($selected['shipment_reference']) ?></textarea></label><label class="span-2"><span>Fulfillment evidence</span><textarea name="fulfillment_evidence" required><?= h($selected['fulfillment_evidence']) ?></textarea></label><div class="span-2 inline-actions"><button class="button primary" type="submit">Save Fulfillment Status</button></div></form><?php endif; ?></section>
